"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["5840"],{2008(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.inscricao.endereco_cep_de_outra_cidade","status":422,"titulo":"O CEP informado pertence a outra cidade que a declarada"},"descricao":{"codigo":"uniplus.selecao.inscricao.endereco_cep_de_outra_cidade","requisitos":["UNI-REQ-0214"],"oQueAconteceu":["O endere\xe7o da inscri\xe7\xe3o \xe9 conferido pelo CEP no Geo, o cadastro de\\nlocalidades do Uni+, ao salvar o rascunho e ao enviar a inscri\xe7\xe3o. O Geo\\nresolveu o CEP para uma cidade ou uma UF diferente da que o candidato\\ndeclarou no endere\xe7o.","A compara\xe7\xe3o \xe9 pelo c\xf3digo da cidade e pela UF. No rascunho, \xe9 s\xf3 essa\\nconfer\xeancia de CEP, c\xf3digo e UF, e o endere\xe7o \xe9 gravado como veio. No\\nenvio, o nome da cidade que o navegador mandou tamb\xe9m deixa de valer: o\\nnome gravado \xe9 o que o Geo resolve pelo CEP."],"comoResolver":["Confira se o CEP e a cidade combinam. Se o CEP est\xe1 certo, escolha no\\nendere\xe7o a cidade e a UF a que ele pertence. Se a cidade est\xe1 certa,\\ncorrija o CEP para um da mesma cidade.","Se usar o CEP geral da cidade, descreva o endere\xe7o real no complemento e\\npreencha tamb\xe9m o logradouro e o bairro, que passam a ser obrigat\xf3rios. Se\\no formul\xe1rio pedir que voc\xea confirme o endere\xe7o, fa\xe7a a confirma\xe7\xe3o antes\\nde enviar. Sem essas informa\xe7\xf5es, o envio \xe9 recusado de novo, por outro\\nmotivo.","Depois de corrigir, envie a inscri\xe7\xe3o outra vez; se ela ainda \xe9 rascunho,\\nvoc\xea tamb\xe9m pode salvar antes. Nada desta tentativa foi gravado."],"ondeAparece":["Grava\xe7\xe3o do rascunho da inscri\xe7\xe3o","Envio da inscri\xe7\xe3o do candidato"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Inscricao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);